// Builds Assets/Art/Street/Resources/street-security-guard-v1.png from the supporters' own sprites:
// the guard is the bald bearded La Renga supporter (same head, face, hands, shoes and outline) dressed in the
// "TECH SEGURIDAD" uniform: hi-vis yellow jacket with long sleeves, orange lower panel and checkered bands,
// black trousers and a black cap. Nothing is generated by an AI service: the uniform is painted over the
// original pixels with CoreGraphics (polygons per frame + colour classes).
//
// Atlas (1024x256, four 256 px cells): 0 = walk A, 1 = walk B (3/4 view to the right), 2 = front A, 3 = front B.
// Usage: swift tools/art/make_guard_from_fans.swift <fans-dir> <output.png> [debug-dir]
import Foundation
import CoreGraphics
import CoreText
import ImageIO

let N = 256
let args = CommandLine.arguments
guard args.count >= 3 else { fatalError("usage: make_guard_from_fans.swift <fans-dir> <output.png> [debug-dir]") }
let fansDir = args[1], outPath = args[2], debugDir = args.count > 3 ? args[3] : nil
let space = CGColorSpaceCreateDeviceRGB()

func loadImage(_ path: String) -> CGImage {
    let src = CGImageSourceCreateWithURL(URL(fileURLWithPath: path) as CFURL, nil)!
    return CGImageSourceCreateImageAtIndex(src, 0, nil)!
}
func savePNG(_ image: CGImage, _ path: String) {
    let dest = CGImageDestinationCreateWithURL(URL(fileURLWithPath: path) as CFURL, "public.png" as CFString, 1, nil)!
    CGImageDestinationAddImage(dest, image, nil)
    guard CGImageDestinationFinalize(dest) else { fatalError("cannot write \(path)") }
}

// MARK: pixel buffer (straight alpha)
struct Px { var r: Float, g: Float, b: Float, a: Float }
final class Cell {
    var px: [Px]
    init(from sheet: CGImage, col: Int, row: Int) {
        let cropped = sheet.cropping(to: CGRect(x: col * N, y: row * N, width: N, height: N))!
        var data = [UInt8](repeating: 0, count: N * N * 4)
        let ctx = CGContext(data: &data, width: N, height: N, bitsPerComponent: 8, bytesPerRow: N * 4, space: space,
                            bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)!
        ctx.draw(cropped, in: CGRect(x: 0, y: 0, width: N, height: N))
        px = (0..<(N * N)).map { i in
            let a = Float(data[i * 4 + 3]); if a == 0 { return Px(r: 0, g: 0, b: 0, a: 0) }
            return Px(r: Float(data[i * 4]) * 255 / a, g: Float(data[i * 4 + 1]) * 255 / a, b: Float(data[i * 4 + 2]) * 255 / a, a: a)
        }
    }
    subscript(x: Int, y: Int) -> Px {
        get { px[y * N + x] }
        set { px[y * N + x] = newValue }
    }
    func image() -> CGImage {
        var data = [UInt8](repeating: 0, count: N * N * 4)
        for i in 0..<(N * N) {
            let p = px[i], a = p.a / 255
            data[i * 4] = UInt8(max(0, min(255, p.r * a))); data[i * 4 + 1] = UInt8(max(0, min(255, p.g * a)))
            data[i * 4 + 2] = UInt8(max(0, min(255, p.b * a))); data[i * 4 + 3] = UInt8(max(0, min(255, p.a)))
        }
        let ctx = CGContext(data: &data, width: N, height: N, bitsPerComponent: 8, bytesPerRow: N * 4, space: space,
                            bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)!
        return ctx.makeImage()!
    }
}

// MARK: geometry helpers (cell coordinates, y from the top)
typealias Poly = [CGPoint]
func P(_ x: CGFloat, _ y: CGFloat) -> CGPoint { CGPoint(x: x, y: y) }
func inside(_ poly: Poly, _ x: Int, _ y: Int) -> Bool {
    let px = CGFloat(x) + 0.5, py = CGFloat(y) + 0.5
    var c = false, j = poly.count - 1
    for i in 0..<poly.count {
        if (poly[i].y > py) != (poly[j].y > py) && px < (poly[j].x - poly[i].x) * (py - poly[i].y) / (poly[j].y - poly[i].y) + poly[i].x { c.toggle() }
        j = i
    }
    return c
}
func mask(_ polys: [Poly]) -> [Bool] {
    var m = [Bool](repeating: false, count: N * N)
    for y in 0..<N { for x in 0..<N { for p in polys where inside(p, x, y) { m[y * N + x] = true; break } } }
    return m
}
// distance (px) to the nearest pixel outside the mask, capped at `cap`
func edgeDistance(_ m: [Bool], cap: Int = 9) -> [Int] {
    var d = [Int](repeating: cap, count: N * N)
    for y in 0..<N { for x in 0..<N where m[y * N + x] {
        var best = cap
        for dy in -cap...cap { for dx in -cap...cap {
            let nx = x + dx, ny = y + dy
            if nx < 0 || ny < 0 || nx >= N || ny >= N || !m[ny * N + nx] { best = min(best, Int((Float(dx * dx + dy * dy)).squareRoot().rounded())) }
        } }
        d[y * N + x] = best
    } }
    return d
}

// MARK: colour classes
func isSkin(_ p: Px) -> Bool { p.r > 140 && p.r > p.g + 20 && p.g > p.b + 5 && p.g > 80 }
func isDenim(_ p: Px) -> Bool { p.b > p.r + 12 && p.b > 55 }
func isNeutralDark(_ p: Px) -> Bool { let m = max(p.r, p.g, p.b); return m >= 24 && m < 115 && p.r - p.b <= 14 }   // shirt (not the near-black outline, not the brown beard)
func isSkinLoose(_ p: Px) -> Bool { p.r > 105 && p.r > p.g + 10 && p.g > p.b + 2 && p.a > 20 }                     // also anti-aliased skin edges
func isInk(_ p: Px) -> Bool { max(p.r, p.g, p.b) < 60 }
func mix(_ a: (Float, Float, Float), _ b: (Float, Float, Float), _ t: Float) -> (Float, Float, Float) {
    let k = max(0, min(1, t)); return (a.0 + (b.0 - a.0) * k, a.1 + (b.1 - a.1) * k, a.2 + (b.2 - a.2) * k)
}
func lum(_ p: Px) -> Float { 0.3 * p.r + 0.59 * p.g + 0.11 * p.b }

let yellowTop: (Float, Float, Float) = (246, 252, 104), yellowBottom: (Float, Float, Float) = (190, 214, 26)
let orangeTop: (Float, Float, Float) = (255, 164, 56), orangeBottom: (Float, Float, Float) = (214, 112, 14)
let silver: (Float, Float, Float) = (232, 232, 224), cream: (Float, Float, Float) = (250, 246, 236), blackCheck: (Float, Float, Float) = (36, 34, 38)

