// MARK: uniform painting
func dress(_ f: Frame, _ cell: Cell) {
    // 1. erase the shirt print (lion) so the shirt is a flat dark surface
    for y in Int(f.printRect.minY)..<Int(f.printRect.maxY) { for x in Int(f.printRect.minX)..<Int(f.printRect.maxX) {
        var p = cell[x, y]; if p.a > 128 && !isDenim(p) && !(isSkin(p) && y > 170) { p.r = 33; p.g = 30; p.b = 30; cell[x, y] = p }
    } }
    // 2. masks
    let inTorso = mask([f.torso]), inSleeve = mask(f.sleeves), inCuff = mask(f.cuffs), inPantsSkin = mask(f.pantsSkin)
    var torso = [Bool](repeating: false, count: N * N), sleeve = torso, pants = torso
    var minY = N, maxY = 0
    for y in 0..<N { for x in 0..<N {
        let i = y * N + x, p = cell[x, y]; if p.a < 20 { continue }
        if p.a >= 128 && inTorso[i] && isNeutralDark(p) && !isSkin(p) && !isDenim(p) { torso[i] = true; minY = min(minY, y); maxY = max(maxY, y) }
        if p.a >= 128 && inSleeve[i] && !isInk(p) { sleeve[i] = true }
        if isDenim(p) || (inPantsSkin[i] && isSkinLoose(p)) { pants[i] = true }
    } }
    let tDist = edgeDistance(torso), sDist = edgeDistance(sleeve)
    let span = Float(max(1, maxY - minY))
    for y in 0..<N { for x in 0..<N {
        let i = y * N + x; var p = cell[x, y]; let a = p.a
        if torso[i] || sleeve[i] {
            let isTorso = torso[i]
            let d = Float(isTorso ? tDist[i] : sDist[i])
            var c: (Float, Float, Float)
            let split = Float(f.panelSplit)
            if isTorso && Float(y) >= split {
                c = mix(orangeTop, orangeBottom, (Float(y) - split) / max(1, Float(maxY) - split))
            } else {
                c = mix(yellowTop, yellowBottom, isTorso ? (Float(y) - Float(minY)) / span : 0.35 + 0.4 * Float(x % 60) / 60)
            }
            if isTorso && Float(y) >= split - 8 && Float(y) < split { c = (Int(Float(x) / 6) + Int((Float(y) - split + 8) / 4)) % 2 == 0 ? blackCheck : cream }   // checkered band
            if isTorso && abs(Float(y) - Float(f.stripeY)) <= 2.5 { c = silver }                                                              // reflective stripe
            let edge = max(0, (7 - d) / 7)                                                                                                   // darker towards the edges (cel shading)
            c = (c.0 * (1 - 0.30 * edge), c.1 * (1 - 0.26 * edge), c.2 * (1 - 0.40 * edge))
            if Float(x) < 110 && !isTorso { c = mix(c, (255, 255, 200), 0.10) }
            p = Px(r: c.0, g: c.1, b: c.2, a: a)
        } else if pants[i] {
            let base = isDenim(p) ? Float(100) : Float(150)
            let l = max(14, min(78, 24 + (lum(p) - base) * 0.42))
            p = Px(r: l, g: l, b: l + 6, a: a)
        }
        if inCuff[i] && sleeve[i] {   // checkered cuff
            let c = (Int(Float(x) / 6) + Int(Float(y) / 6)) % 2 == 0 ? blackCheck : cream
            p = Px(r: c.0, g: c.1, b: c.2, a: a)
        }
        cell[x, y] = p
    } }
}

// MARK: cap + chest text (drawn with CoreGraphics over the repainted cell)
func ellipsePath(_ c: CGPoint, _ rx: CGFloat, _ ry: CGFloat) -> CGPath { CGPath(ellipseIn: CGRect(x: c.x - rx, y: c.y - ry, width: rx * 2, height: ry * 2), transform: nil) }
func gradient(_ a: CGColor, _ b: CGColor) -> CGGradient { CGGradient(colorsSpace: space, colors: [a, b] as CFArray, locations: [0, 1])! }
func col(_ v: UInt32, _ a: CGFloat = 1) -> CGColor { CGColor(red: CGFloat((v >> 16) & 255) / 255, green: CGFloat((v >> 8) & 255) / 255, blue: CGFloat(v & 255) / 255, alpha: a) }
let ink = col(0x1B0C08)

func overlay(_ f: Frame, _ base: CGImage) -> CGImage {
    let ctx = CGContext(data: nil, width: N, height: N, bitsPerComponent: 8, bytesPerRow: 0, space: space, bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)!
    ctx.interpolationQuality = .high
    ctx.draw(base, in: CGRect(x: 0, y: 0, width: N, height: N))
    ctx.translateBy(x: 0, y: CGFloat(N)); ctx.scaleBy(x: 1, y: -1)     // y from the top from here on
    let c = f.cap
    func fill(_ path: CGPath, _ top: CGColor, _ bottom: CGColor, lw: CGFloat = 4.4) {
        let b = path.boundingBox
        ctx.saveGState(); ctx.addPath(path); ctx.clip()
        ctx.drawLinearGradient(gradient(top, bottom), start: P(b.midX, b.minY), end: P(b.midX, b.maxY), options: [])
        ctx.restoreGState()
        ctx.addPath(path); ctx.setStrokeColor(ink); ctx.setLineWidth(lw); ctx.setLineJoin(.round); ctx.strokePath()
    }
    // dome: upper half of an ellipse closed by a slightly curved band line
    let dome = CGMutablePath()
    dome.move(to: P(c.center.x - c.rx, c.center.y))
    for k in 1...48 { let a = .pi + CGFloat(k) / 48 * .pi; dome.addLine(to: P(c.center.x + cos(a) * c.rx, c.center.y + sin(a) * c.ry)) }
    dome.addQuadCurve(to: P(c.center.x - c.rx, c.center.y), control: P(c.center.x, c.center.y + 12))
    dome.closeSubpath()
    fill(dome, col(0x4B4B57), col(0x16161B))
    ctx.saveGState(); ctx.addPath(dome); ctx.clip()
    ctx.setFillColor(col(0xFFFFFF, 0.16)); ctx.fillEllipse(in: CGRect(x: c.center.x - c.rx * 0.62, y: c.center.y - c.ry + 5, width: c.rx * 0.78, height: 8))
    ctx.setStrokeColor(col(0x0C0C10, 0.6)); ctx.setLineWidth(2); ctx.move(to: P(c.center.x + (c.side ? 14 : 0), c.center.y - c.ry)); ctx.addLine(to: P(c.center.x + (c.side ? 14 : 0), c.center.y + 6)); ctx.strokePath()
    ctx.restoreGState()
    ctx.saveGState(); ctx.setFillColor(col(0x3A3A44)); ctx.setStrokeColor(ink); ctx.setLineWidth(3)
    let button = ellipsePath(P(c.center.x + (c.side ? 14 : 0), c.center.y - c.ry + 1), 5, 3.4); ctx.addPath(button); ctx.drawPath(using: .fillStroke); ctx.restoreGState()
    // brim
    ctx.saveGState(); ctx.translateBy(x: c.brimCenter.x, y: c.brimCenter.y); ctx.rotate(by: c.brimTilt); ctx.translateBy(x: -c.brimCenter.x, y: -c.brimCenter.y)
    fill(ellipsePath(c.brimCenter, c.brimRx, c.brimRy), col(0x50505C), col(0x1A1A20), lw: 4)
    ctx.restoreGState()
    // logo patch
    let patch = CGPath(roundedRect: CGRect(x: c.patch.x - 12, y: c.patch.y - 7.5, width: 24, height: 15), cornerWidth: 4, cornerHeight: 4, transform: nil)
    fill(patch, col(0xF2524B), col(0xA21A1C), lw: 3)
    ctx.setStrokeColor(col(0xFFFFFF)); ctx.setLineWidth(2.6); ctx.setLineCap(.round)
    ctx.move(to: P(c.patch.x - 7, c.patch.y + 1)); ctx.addLine(to: P(c.patch.x + 7, c.patch.y + 1)); ctx.strokePath()
    ctx.setLineWidth(2); ctx.move(to: P(c.patch.x - 7, c.patch.y - 3.5)); ctx.addLine(to: P(c.patch.x + 1, c.patch.y - 3.5)); ctx.strokePath()
    // chest text on the front view
    if let t = f.tech {
        let font = CTFontCreateWithName("Helvetica-Bold" as CFString, 16, nil)
        let attrs: [NSAttributedString.Key: Any] = [NSAttributedString.Key(rawValue: kCTFontAttributeName as String): font,
                                                    NSAttributedString.Key(rawValue: kCTForegroundColorAttributeName as String): col(0x23232B)]
        let line = CTLineCreateWithAttributedString(NSAttributedString(string: "TECH", attributes: attrs))
        let b = CTLineGetBoundsWithOptions(line, [])
        ctx.saveGState(); ctx.scaleBy(x: 1, y: -1); ctx.translateBy(x: 0, y: -CGFloat(N))
        ctx.textPosition = P(t.x - b.midX, CGFloat(N) - t.y - b.midY); CTLineDraw(line, ctx); ctx.restoreGState()
    }
    return ctx.makeImage()!
}

// MARK: build the atlas
var sheets: [String: CGImage] = [:]
let atlas = CGContext(data: nil, width: N * frames.count, height: N, bitsPerComponent: 8, bytesPerRow: 0, space: space, bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)!
for (i, f) in frames.enumerated() {
    if sheets[f.sheet] == nil { sheets[f.sheet] = loadImage(fansDir + "/" + f.sheet) }
    let cell = Cell(from: sheets[f.sheet]!, col: f.col, row: f.row)
    dress(f, cell)
    let final = overlay(f, cell.image())
    atlas.draw(final, in: CGRect(x: i * N, y: 0, width: N, height: N))
    if let dir = debugDir { savePNG(final, dir + "/guard-" + f.name + ".png") }
}
savePNG(atlas.makeImage()!, outPath)
print("wrote \(outPath) \(N * frames.count)x\(N)")
